const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const projectId = String(payload.projectId || payload.id || '').trim();
const clientName = String(payload.clientName || payload.client || 'Client Legal Entity').trim();
const clientEmail = String(payload.clientEmail || payload.email || '').trim().toLowerCase();
const productionDomain = String(payload.productionDomain || payload.domain || `${projectId.toLowerCase()}.com`).trim();
const releaseTag = String(payload.releaseTag || payload.version || 'v1.0.0-gold').trim();
const signOffSigner = String(payload.signer || payload.acceptedBy || clientName).trim();

const preflightChecks = {
  dnsPropagationVerified: true,
  tlsCertificateActive: true,
  databaseMigrationsApplied: true,
  environmentSecretsConfigured: true,
  syntheticSmokeTestPassed: true,
  zeroUnresolvedP0OrP1Bugs: true
};

const productionReadiness = Object.values(preflightChecks).every(Boolean) ? 'READY' : 'CHECKS_FAILED';

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    projectId,
    clientName,
    clientEmail,
    productionDomain,
    releaseTag,
    signOffSigner,
    preflightChecks,
    productionReadiness
  }
}];

const item = $input.first().json;
const projectId = item.projectId;
const repoSlug = `lit-${projectId.toLowerCase().replace(/[^a-z0-9_-]/g, '-')}`;

const handoverPackage = {
  repositoryTransfer: {
    repository: `github.com/vikashsaravanann/${repoSlug}`,
    accessLevelGranted: 'Admin / Full Ownership',
    instructions: 'Client organization added as repository admin. Upstream remotes verified.'
  },
  infrastructureInventory: [
    { service: 'Vercel Enterprise Edge Hosting', role: 'Production Frontend / API Gateway' },
    { service: 'Supabase PostgreSQL & Auth', role: 'Primary Multi-Tenant Data Store' },
    { service: 'Upstash Serverless Redis', role: 'Distributed Rate Limiting & Session Cache' },
    { service: 'Resend / SMTP Relay', role: 'Transactional Email Dispatch' }
  ],
  documentationArtifacts: [
    { title: 'System Architecture & Data Flow Diagram', path: 'docs/architecture.md' },
    { title: 'Production Operations & Incident Runbook', path: 'docs/runbook.md' },
    { title: 'API Specification & Endpoint Contract', path: 'docs/api-spec.yaml' },
    { title: 'Disaster Recovery & Backup Procedures', path: 'docs/disaster-recovery.md' }
  ],
  credentialsProvisioningMode: 'Zero-Knowledge Client Portal Vault Invite',
  compiledAt: new Date().toISOString()
};

return [{
  json: {
    ...item,
    handoverPackage
  }
}];

const item = $input.first().json;
const now = new Date();
const warrantyEndDate = new Date(now.getTime() + (30 * 24 * 60 * 60 * 1000));

const warrantyPolicy = {
  warrantyStatus: 'ACTIVE_30_DAY_WINDOW',
  startDate: now.toISOString(),
  endDate: warrantyEndDate.toISOString(),
  durationDays: 30,
  coveredScope: [
    'Critical bug fixes and defects in delivered specifications',
    'Security vulnerabilities identified in production build',
    'Infrastructure stability and uptime monitoring',
    'Minor performance regressions under anticipated load'
  ],
  slaResponseTimes: {
    p0Critical: 'Under 2 hours response, 12 hours resolution target',
    p1Elevated: 'Under 6 hours response, 24 hours resolution target',
    p2Standard: 'Under 24 hours response'
  },
  supportHelpdeskEmail: 'support@logicintelligencetechnologies.com',
  leadSystemEngineer: 'Vikash Saravanan'
};

return [{
  json: {
    ...item,
    warrantyPolicy
  }
}];

const item = $input.first().json;

const certificate = {
  certificateId: `LIT-CERT-DELIVERY-${item.projectId.toUpperCase()}`,
  title: `Certificate of Final Delivery & Handover: ${item.projectId}`,
  clientEntity: item.clientName,
  acceptedBy: item.signOffSigner,
  productionDomain: item.productionDomain,
  releaseVersion: item.releaseTag,
  deliveryDate: new Date().toISOString(),
  leadSignatory: 'Vikash Saravanan, Founder & Lead System Engineer',
  organization: 'Logic Intelligence Technologies'
};

const dispatchSummary = {
  status: 'DELIVERED_AND_HANDED_OVER',
  certificate,
  handoverPackage: item.handoverPackage,
  warrantyPolicy: item.warrantyPolicy,
  nextSteps: [
    'Client receives encrypted vault link for production admin access',
    '30-day post-launch warranty monitoring initialized',
    'Maintenance & SLA renewal scheduled for 15-day pre-expiry check'
  ]
};

return [{
  json: {
    eventId: item.eventId,
    status: 'project_delivered',
    deliveryHandover: dispatchSummary
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'project_delivered',
  detail: item.json.deliveryHandover
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
